using System;using System.IO;using System.Text;using System.Reflection;using System.Collections;using UnityEngine;
public static class ClientFixture {
 public static string Run(){if(File.Exists(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-crate-rays.txt"))){var w=GameManager.Instance.World;var s=new StringBuilder();for(int i=0;i<3;i++){int x=-2620+i*3,z=-2140,y=w.GetTerrainHeight(x,z)+1;var pos=new Vector3i(x,y,z);bool hit=false;for(float h=.2f;h<1.1f;h+=.2f){var ray=new Ray(new Vector3(x+.5f,y+h,z-3),Vector3.forward);if(Voxel.Raycast(w,ray,5,Voxel.HM_Melee,0)&&Voxel.voxelRayHitInfo.hit.blockPos==pos&&Voxel.voxelRayHitInfo.hitCollider!=null&&Voxel.voxelRayHitInfo.hitCollider.tag=="T_Block"){hit=true;break;}}if(!hit)throw new Exception("Crate native ray target missing "+pos);s.AppendLine("PASS native interaction/harvest ray targets crate at "+pos);}File.WriteAllText(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-crate-rays-result.txt"),s.ToString());return s.ToString();}if(File.Exists(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-crate-diag.txt"))){var w=GameManager.Instance.World;var s=new StringBuilder();for(int y=0;y<256;y++){var pos=new Vector3i(-2620,y,-2140);var b=w.GetBlock(pos);if(!b.Block.GetBlockName().StartsWith("cntShoppingCart"))continue;var te=w.GetTileEntity(pos);s.AppendLine(pos+" "+b.Block.GetType()+" te="+te+" remote="+w.IsRemote());if(te is TileEntityComposite){var st=((TileEntityComposite)te).GetFeature<TEFeatureStorage>();s.AppendLine("STORAGE="+st);}foreach(var c in b.Block.GetBlockActivationCommands(w,b,pos,w.GetPrimaryPlayer()))s.AppendLine("COMMAND "+c.text);}return s.ToString();}if(File.Exists(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-reload-ui.txt"))){var p=GameManager.Instance.World.GetPrimaryPlayer();if(p.Progression.GetProgressionValue("delveAttStrength").Level!=3||p.Progression.GetProgressionValue("delvePerkBladesBladeFamiliarity").Level!=1||p.Progression.SkillPoints!=0)throw new Exception("Purchased progression did not survive reload");File.WriteAllText(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-ui-reload.txt"),"PASS attribute rank 3, purchased combat perk and zero remaining skill points persisted through native disconnect/rejoin");return "PASS progression reload";}if(File.Exists(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-wall.txt"))){var w=GameManager.Instance.World;var s=new StringBuilder();for(int x=-2709;x<=-2707;x++)for(int y=63;y<=70;y++){var b=w.GetBlock(x,y,-2172);s.AppendLine(x+","+y+" "+b.Block.GetBlockName()+" density="+w.GetDensity(x,y,-2172)+" terrain="+b.isTerrain);}File.WriteAllText(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-wall-diagnostic.txt"),s.ToString());return s.ToString();}if(File.Exists(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-switch.txt"))){new GameObject("BatchThreeSwitch").AddComponent<BatchThreeSwitchSave>();return "Switching to copied save";}if(File.Exists(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-world.txt"))){new GameObject("BatchThreeWorld").AddComponent<BatchThreeWorldAcceptance>();return "Started world acceptance";}if(File.Exists(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-carts.txt")))return BatchThreeCartPrefabs.Run();if(File.Exists(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-ui.txt"))){new GameObject("BatchThreeUiAcceptance").AddComponent<BatchThreeUiAcceptance>();return "Started UI acceptance";}if(File.Exists(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-prefabs.txt")))return BatchThreePrefabTools.Run();if(File.Exists(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-quit.txt"))){Application.Quit();return "Quit test client";}new GameObject("BatchThreeInspection").AddComponent<BatchThreeInspection>();return "Started Batch 3 inspection";}
}
public class BatchThreeInspection:MonoBehaviour {
 IEnumerator Start(){var p=GameManager.Instance.World.GetPrimaryPlayer();p.IsGodMode.Value=true;p.PlayerUI.windowManager.Close("spawnselection");p.PlayerUI.windowManager.ReEnableHUD();p.PlayerUI.windowManager.Open("skills",true);yield return new WaitForSeconds(2);
 var s=new StringBuilder();var group=p.PlayerUI.xui.FindWindowGroupByName("skills");var screen=group.GetChildByType<Delve.XUiC_ProgressionScreen>();s.AppendLine("SCREEN="+screen+" GROUP="+group);
 if(screen!=null){foreach(var f in screen.GetType().GetFields(BindingFlags.Instance|BindingFlags.NonPublic))s.AppendLine(f.Name+"="+f.GetValue(screen));string v="";s.AppendLine("BUDGET="+screen.GetBindingValueInternal(ref v,"dg_budget")+" "+v);var budget=screen.GetChildById("budget");for(var c=budget;c!=null;c=c.Parent)s.AppendLine("CHAIN="+c.GetType()+" "+c.GetXuiHierarchy());s.AppendLine("LABEL="+((XUiV_Label)budget.ViewComponent).Text);screen.OnOpen();yield return new WaitForSeconds(1);s.AppendLine("AFTER EXPLICIT OPEN="+((XUiV_Label)budget.ViewComponent).Text);}
 File.WriteAllText(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-inspection.txt"),s.ToString());Capture("skills");yield return new WaitForSeconds(1);
 p.PlayerUI.windowManager.Close("skills");p.SetFirstPersonView(true,false);
 foreach(string id in new[]{"meleeWpnSpearT0StoneSpear","delveAshSpear","delveForgedSpear"}){
 p.inventory.SetItem(0,ItemClass.GetItem(id,false),1);p.inventory.SetHoldingItemIdxNoHolsterTime(0);yield return new WaitForSeconds(2);Capture(id);yield return new WaitForSeconds(.3f);
 var model=p.inventory.holdingItemData.model;s.AppendLine("MODEL "+id);foreach(var t in model.GetComponentsInChildren<Transform>(true))s.AppendLine(t.name+" p="+t.localPosition.ToString("F4")+" r="+t.localEulerAngles.ToString("F2"));foreach(var mr in model.GetComponentsInChildren<MeshFilter>(true))s.AppendLine("BOUNDS "+mr.name+" "+mr.sharedMesh.bounds.ToString("F4"));
 }
 foreach(string path in new[]{"@:Shapes/ramp.fbx","@:Entities/LootContainers/groceryCartFullPrefab.prefab","@:Entities/LootContainers/groceryCartEmptyPrefab.prefab","@:Entities/LootContainers/groceryCartTippedPrefab.prefab"}){var g=DataLoader.LoadAsset<GameObject>(path,true);s.AppendLine("ASSET "+path);if(g!=null)foreach(var m in g.GetComponentsInChildren<MeshFilter>(true)){s.AppendLine("MESH "+m.name+" "+m.sharedMesh.bounds.ToString("F4"));if(path.Contains("ramp"))foreach(var v in m.sharedMesh.vertices)s.AppendLine("VERT "+v);}}
 File.WriteAllText(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-inspection.txt"),s.ToString());Destroy(gameObject);
 }
 void Capture(string n){Type.GetType("UnityEngine.ScreenCapture, UnityEngine.ScreenCaptureModule").GetMethod("CaptureScreenshot",new[]{typeof(string),typeof(int)}).Invoke(null,new object[]{Path.Combine(GameIO.GetUserGameDataDir(),"batch03-"+n+".png"),1});}
}



